#!/usr/bin/env node
'use strict';

// Generate _locales/<locale>/messages.json files for every supported
// non-English locale by mapping each English message through a per-locale
// translation table. Brand names ("Astra Deck", "Astra Downloader",
// "DeArrow", "SponsorBlock") and technical formats ("MP4", "M4A", "VP9",
// "YouTube", "TrustedTypes") stay English by convention.
//
// Run via: `node scripts/generate-locales.js`
//
// The translation tables below are intentionally inline rather than in
// separate JSON files so adding/maintaining a locale is a single PR with
// the diff visible in code review. Translations were authored from the
// canonical English; native-speaker proofing is a recommended follow-up.

const fs = require('fs');
const path = require('path');
const {
    DO_NOT_TRANSLATE_TERMS,
    missingProtectedTerms
} = require('./i18n-policy');

const ROOT = path.join(__dirname, '..');
const EN_PATH = path.join(ROOT, 'extension', '_locales', 'en', 'messages.json');
const en = JSON.parse(fs.readFileSync(EN_PATH, 'utf8'));

// Tokens that should NEVER be translated are kept in scripts/i18n-policy.js.
// The generator checks translated strings preserve them verbatim.
//
//   Reviewed terms: Astra Deck, Astra Downloader, DeArrow, SponsorBlock,
//   YouTube, MP4, M4A, VP9, AV1, H.264, TrustedTypes, ETA

// LOCALES: locale-code → { language label in own script, translations map }
// Each translations map is keyed by English message → translated message.
// Keys in messages.json that don't have an entry in the map preserve the
// checked-in locale string when one already exists, otherwise they fall back to
// the English text. This keeps the generator from wiping proofed strings added
// directly to locale files during earlier translation passes.

const T = {};

// Arabic and Simplified Chinese were originally proofed directly in their
// locale catalogs. Include them in generation so newly extracted keys retain
// parity while those checked-in translations remain authoritative.
T.ar = {};
T.zh_CN = {};

